/**
 * Review diff on the site: an agent's edit to a team invite form, four changes to review and one thread on a line.
 * A premium element: this example is free to read, the element installs with FoundKeep Pro.
 */
import { ReviewDiff, type ReviewDiffThread } from "@/components/application/premium/review-diff";

const BEFORE = `import { useState } from "react";
import { sendInvite } from "../api/invites";
import { RoleSelect, type Role } from "./RoleSelect";
import { Avatar } from "../ui/Avatar";

type Invitee = {
  email: string;
  role: Role;
};

type Props = {
  teamId: string;
  seatsLeft: number;
  pending: Invitee[];
  onInvited?: (invitee: Invitee) => void;
};

function seatLabel(seatsLeft: number) {
  if (seatsLeft <= 0) return "No seats left";
  if (seatsLeft === 1) return "1 seat left";
  return \`\${seatsLeft} seats left\`;
}

export function InviteForm({ teamId, seatsLeft, pending, onInvited }: Props) {
  const [email, setEmail] = useState("");
  const [role, setRole] = useState<Role>("member");
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    if (!email.includes("@")) {
      setError("Enter an email address");
      return;
    }
    await sendInvite(teamId, { email, role });
    onInvited?.({ email, role });
    setEmail("");
  }

  return (
    <form onSubmit={handleSubmit} className="invite">
      <header className="invite-head">
        <h2>Invite people</h2>
        <p className="invite-seats">{seatLabel(seatsLeft)}</p>
      </header>

      <label htmlFor="invite-email">Email</label>
      <input
        id="invite-email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder="name@company.com"
      />

      <label htmlFor="invite-role">Role</label>
      <RoleSelect id="invite-role" value={role} onChange={setRole} />

      {pending.length > 0 && (
        <ul className="invite-pending">
          {pending.map((person) => (
            <li key={person.email}>
              <Avatar name={person.email} size={20} />
              <span>{person.email}</span>
              <span className="invite-role">{person.role}</span>
            </li>
          ))}
        </ul>
      )}

      {error && <p className="invite-error">{error}</p>}

      <button type="submit" disabled={seatsLeft <= 0}>
        Send invite
      </button>
    </form>
  );
}`;

const AFTER = `import { useState } from "react";
import { sendInvite } from "../api/invites";
import { RoleSelect, type Role } from "./RoleSelect";
import { Avatar } from "../ui/Avatar";

const EMAIL = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;

type Invitee = {
  email: string;
  role: Role;
};

type Props = {
  teamId: string;
  seatsLeft: number;
  pending: Invitee[];
  onInvited?: (invitee: Invitee) => void;
};

function seatLabel(seatsLeft: number) {
  if (seatsLeft <= 0) return "No seats left";
  if (seatsLeft === 1) return "1 seat left";
  return \`\${seatsLeft} seats left\`;
}

export function InviteForm({ teamId, seatsLeft, pending, onInvited }: Props) {
  const [email, setEmail] = useState("");
  const [role, setRole] = useState<Role>("member");
  const [error, setError] = useState<string | null>(null);
  const [sending, setSending] = useState(false);

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    const address = email.trim().toLowerCase();
    if (!EMAIL.test(address)) {
      setError("Enter a full email address, like sam@example.com");
      return;
    }
    setSending(true);
    try {
      await sendInvite(teamId, { email: address, role });
      onInvited?.({ email: address, role });
      setEmail("");
      setError(null);
    } catch {
      setError("The invite didn't send. Check your connection and try again.");
    } finally {
      setSending(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="invite">
      <header className="invite-head">
        <h2>Invite people</h2>
        <p className="invite-seats">{seatLabel(seatsLeft)}</p>
      </header>

      <label htmlFor="invite-email">Email</label>
      <input
        id="invite-email"
        type="email"
        autoComplete="off"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder="name@company.com"
      />

      <label htmlFor="invite-role">Role</label>
      <RoleSelect id="invite-role" value={role} onChange={setRole} />

      {pending.length > 0 && (
        <ul className="invite-pending">
          {pending.map((person) => (
            <li key={person.email}>
              <Avatar name={person.email} size={20} />
              <span>{person.email}</span>
              <span className="invite-role">{person.role}</span>
            </li>
          ))}
        </ul>
      )}

      {error && (
        <p className="invite-error" role="alert">
          {error}
        </p>
      )}

      <button type="submit" disabled={sending || seatsLeft <= 0}>
        {sending ? "Sending…" : "Send invite"}
      </button>
    </form>
  );
}`;

/** What the agent says each change does, in order. */
const CHANGES = [
  "Add a pattern for email addresses",
  "Check the address and handle failed sends",
  "Use the email keyboard on phones",
  "Announce errors and stop double sends",
];

const THREADS: ReviewDiffThread[] = [
  {
    line: "const address = email.trim().toLowerCase();",
    comments: [
      { author: "Sprocket", color: "#b4531f", when: "2 hours ago", text: "Lowercasing is right for invites. Let’s not copy it into sign-in." },
      { author: "Agent", kind: "agent", when: "1 hour ago", text: "Agreed. Only this form lowercases. Sign-in still compares what people type." },
    ],
  },
];

export default function ReviewDiffDemo() {
  return (
    <div style={{ width: "100%", height: 600 }}>
      <ReviewDiff oldText={BEFORE} newText={AFTER} path="src/features/team/InviteForm.tsx" badge="Agent edit" hunkTitles={CHANGES} threads={THREADS} />
    </div>
  );
}

